import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import GameHeader from "./shared/GameHeader";
import { COP, chips as defaultChips } from "../../data/games";
import deathFeathersVideo from "../../assets/death_feathers.mp4";

/* ============================================================
   ASSETS (sprites del usuario, incrustados en base64)
   ============================================================ */
const IMG_ROAD_START = "data:image/jpeg;base64,";
const IMG_ROAD_REPEAT = "data:image/jpeg;base64,";
const IMG_CONE = "data:image/png;base64,";
const IMG_CHICKEN = "data:image/png;base64,";
const IMG_DRAIN = "data:image/png;base64,";

/* ============================================================
   CONFIGURACION DEL TABLERO
   ============================================================ */
type LaneState = "pending" | "safe" | "crashed";
type GameState = "betting" | "playing" | "crashed" | "won";

const LANE_WIDTH = 92;
const START_WIDTH = 118;
const BOARD_HEIGHT = 460;
const VIEWPORT_WIDTH = START_WIDTH + 3 * LANE_WIDTH; // Ancho recortado: pasto inicial + 3 alcantarillas
const DRAIN_Y_PERCENT = 58; // posicion vertical de la alcantarilla dentro del carril
const JUMP_MS = 420;
const RUSH_MS = 280; // ms que tarda el carro en llegar a toda velocidad al pollo tras detectar crash

const MULTIPLIERS = [1.12, 1.28, 1.49, 1.76, 2.12, 2.62, 3.35, 4.6, 6.9, 11.4];
const SURVIVAL_CHANCE = [94, 90, 86, 81, 75, 68, 59, 48, 35, 20]; // % de cruzar con exito
const LANE_COUNT = MULTIPLIERS.length;

const STARTING_BALANCE = 1000;

/* ============================================================
   COMPONENTE: Animación de Muerte en Pantalla Verde (Chroma-Key)
   Elimina el fondo verde mediante canvas y reproduce la explosión
   de plumas al atropellar a la gallina.
   ============================================================ */
function ChromaKeyDeath({
  src,
  playing,
  onEnded,
}: {
  src: string;
  playing: boolean;
  onEnded?: () => void;
}) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number>(0);

  const processFrame = useCallback(() => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas || video.paused || video.ended) return;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) return;

    if (video.videoWidth && video.videoHeight) {
      if (canvas.width !== video.videoWidth) canvas.width = video.videoWidth;
      if (canvas.height !== video.videoHeight) canvas.height = video.videoHeight;
    }

    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const frame = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const d = frame.data;
    for (let i = 0; i < d.length; i += 4) {
      const r = d[i];
      const g = d[i + 1];
      const b = d[i + 2];

      // Diferencia entre el canal verde y los otros dos
      const diffRG = g - r;
      const diffGB = g - b;

      // Zona CORE verde: eliminar completamente
      if (g > 60 && diffRG > 20 && diffGB > 10) {
        d[i + 3] = 0;
      }
      // Zona de BORDE (semi-transparente para suavizar): transición gradual
      else if (g > 50 && diffRG > 8 && diffGB > 4) {
        // Alfa proporcional a qué tan "verde" es el píxel
        const greenness = Math.min(diffRG, diffGB) / 20;
        d[i + 3] = Math.round(d[i + 3] * (1 - greenness));
        // Supresión de derrame verde (green spill): reducir el canal G
        d[i + 1] = Math.min(d[i + 1], Math.max(r, b));
      }
      // Supresión de derrame verde suave en píxeles visibles con tinte verde
      else if (g > r && g > b) {
        d[i + 1] = Math.round((r + b) / 2);
      }
    }
    ctx.putImageData(frame, 0, 0);
    rafRef.current = requestAnimationFrame(processFrame);
  }, []);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    if (playing) {
      video.currentTime = 0;
      video.playbackRate = 1.75;
      video.play().then(() => {
        processFrame();
      }).catch(() => {});
      rafRef.current = requestAnimationFrame(processFrame);
    } else {
      video.pause();
      cancelAnimationFrame(rafRef.current);
    }
    return () => cancelAnimationFrame(rafRef.current);
  }, [playing, processFrame]);

  return (
    <div style={{
      position: "relative",
      width: 100,
      height: 100,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      borderRadius: "50%",
      overflow: "hidden",
    }}>
      <video
        ref={videoRef}
        src={src}
        muted
        playsInline
        preload="auto"
        onEnded={onEnded}
        style={{ display: "none" }}
      />
      <canvas
        ref={canvasRef}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          pointerEvents: "none",
          clipPath: "circle(50% at 50% 50%)",
        }}
      />
    </div>
  );
}

/* ============================================================
   COMPONENTE: Auto visto desde arriba (pixel, dibujado con SVG
   ya que no se proporciono sprite de auto)
   ============================================================ */
function TopDownCar({ tone }: { tone: string }) {
  return (
    <svg width="34" height="58" viewBox="0 0 34 58" shapeRendering="crispEdges">
      <rect x="6" y="2" width="22" height="54" fill="#0b0b0f" />
      <rect x="8" y="4" width="18" height="50" fill={tone} />
      <rect x="10" y="8" width="14" height="10" fill="#bfe3ff" />
      <rect x="10" y="40" width="14" height="10" fill="#bfe3ff" />
      <rect x="8" y="20" width="18" height="18" fill={tone} />
      <rect x="6" y="10" width="4" height="8" fill="#0b0b0f" />
      <rect x="24" y="10" width="4" height="8" fill="#0b0b0f" />
      <rect x="6" y="40" width="4" height="8" fill="#0b0b0f" />
      <rect x="24" y="40" width="4" height="8" fill="#0b0b0f" />
      <rect x="12" y="24" width="4" height="4" fill="#fff1b8" />
      <rect x="18" y="24" width="4" height="4" fill="#fff1b8" />
    </svg>
  );
}

const CAR_TONES = [
  "#ff6a3d",
  "#ffd23d",
  "#8a5cff",
  "#3ddcff",
  "#ff3d6a",
  "#3dff8a",
  "#ff3d3d",
  "#ffb23d",
  "#6a3dff",
  "#3d8aff",
];

/* ============================================================
   COMPONENTE PRINCIPAL
   ============================================================ */
interface ChickenRoadProps {
  title: string;
  name: string;
  balance: number;
  change: (delta: number, wagered?: number) => void;
  notify: (msg: string) => void;
  back: () => void;
}

export default function ChickenRoadCasino({ title, name, balance, change, notify, back }: ChickenRoadProps) {
  // Valores de moneda idénticos a los demás juegos (defaultChips: 10000, 25000, 100000, 500000)
  const [bet, setBet] = useState(25000);
  const [gameState, setGameState] = useState<GameState>("betting");
  const [currentLane, setCurrentLane] = useState(0); // 0 = pasto inicial
  const [laneStates, setLaneStates] = useState<LaneState[]>(
    Array(LANE_COUNT).fill("pending")
  );
  const [isJumping, setIsJumping] = useState(false);
  const [jumpArc, setJumpArc] = useState(false);
  const [crashedLane, setCrashedLane] = useState<number | null>(null);
  const [fallingIn, setFallingIn] = useState(false);
  // 'none' = normal | 'rushing' = carro bajando rapido | 'hit' = impacto ya ocurrido
  const [crashPhase, setCrashPhase] = useState<'none' | 'rushing' | 'hit'>('none');
  // Animación de muerte (pantalla verde eliminada con chroma-key)
  const [deathAnimPlaying, setDeathAnimPlaying] = useState(false);
  const [deathPosition, setDeathPosition] = useState<{ left: number; top: string } | null>(null);
  // Carril donde el carro baja a toda velocidad a chocar contra el cono
  const [safeRushLane, setSafeRushLane] = useState<number | null>(null);
  const [message, setMessage] = useState("Elige tu apuesta y cruza la carretera.");
  const [flashWin, setFlashWin] = useState<number | null>(null);
  const jumpTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const crashTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const safeRushTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Candado síncrono para prevenir spam-click y evitar saltar tras morir
  const isActionLockedRef = useRef(false);

  const currentMultiplier = currentLane === 0 ? 1 : MULTIPLIERS[currentLane - 1];
  const potentialWin = Math.round(bet * currentMultiplier * 100) / 100;

  // Duraciones/retrasos de autos por carril, generados una vez por ronda
  const [carTimings, setCarTimings] = useState(() => makeCarTimings());

  function makeCarTimings() {
    return Array.from({ length: LANE_COUNT }, (_, i) => {
      const riskFactor = i / LANE_COUNT; // 0..1, mas riesgo = autos mas rapidos
      const duration = 2.6 - riskFactor * 1.7 + Math.random() * 0.4;
      const delay = -Math.random() * duration;
      return { duration: Math.max(0.7, duration), delay };
    });
  }

  useEffect(() => {
    return () => {
      if (jumpTimeout.current) clearTimeout(jumpTimeout.current);
      if (crashTimeout.current) clearTimeout(crashTimeout.current);
      if (safeRushTimeout.current) clearTimeout(safeRushTimeout.current);
    };
  }, []);

  const startRound = useCallback(() => {
    if (bet <= 0 || bet > balance) return;
    if (jumpTimeout.current) clearTimeout(jumpTimeout.current);
    if (crashTimeout.current) clearTimeout(crashTimeout.current);
    if (safeRushTimeout.current) clearTimeout(safeRushTimeout.current);
    isActionLockedRef.current = false;
    change(-bet, bet);
    setGameState("playing");
    setCurrentLane(0);
    setLaneStates(Array(LANE_COUNT).fill("pending"));
    setCrashedLane(null);
    setFallingIn(false);
    setCrashPhase('none');
    setDeathAnimPlaying(false);
    setDeathPosition(null);
    setSafeRushLane(null);
    setCarTimings(makeCarTimings());
    setMessage("¡Salta a la primera alcantarilla!");
    setFlashWin(null);
  }, [bet, balance, change]);

  const jump = useCallback(() => {
    // Si ya está bloqueado, saltando, fuera de partida, en fase de atropello o ya terminó
    if (
      gameState !== "playing" ||
      isJumping ||
      isActionLockedRef.current ||
      crashPhase !== "none" ||
      currentLane >= LANE_COUNT
    ) {
      return;
    }

    // Bloqueo inmediato síncrono contra spam-clicks
    isActionLockedRef.current = true;
    setIsJumping(true);
    setJumpArc(true);
    const targetLane = currentLane + 1;
    const laneIndex = targetLane - 1;

    jumpTimeout.current = setTimeout(() => {
      setJumpArc(false);
      const roll = Math.random() * 100;
      const success = roll < SURVIVAL_CHANCE[laneIndex];

      if (success) {
        setLaneStates((prev) => {
          const next = [...prev];
          next[laneIndex] = "safe";
          return next;
        });
        setCurrentLane(targetLane);
        setIsJumping(false);

        // ¡El carro baja a gran velocidad (la misma que al atropellar al pollo) y choca contra el cono!
        setSafeRushLane(laneIndex);
        if (safeRushTimeout.current) clearTimeout(safeRushTimeout.current);
        safeRushTimeout.current = setTimeout(() => {
          setSafeRushLane((curr) => (curr === laneIndex ? null : curr));
        }, RUSH_MS);

        if (targetLane === LANE_COUNT) {
          const winnings = Math.round(bet * MULTIPLIERS[laneIndex] * 100) / 100;
          setGameState("won");
          change(+winnings);
          setFlashWin(winnings);
          notify(`¡Cruzaste toda la carretera! Ganaste ${COP.format(winnings)}.`);
          setMessage(`¡Cruzaste toda la carretera! Ganaste ${COP.format(winnings)}.`);
        } else {
          setMessage(`¡A salvo! Cono colocado · Multiplicador x${MULTIPLIERS[laneIndex].toFixed(2)}`);
          isActionLockedRef.current = false;
        }
      } else {
        // EN CASO DE MUERTE:
        setGameState("crashed");
        setCurrentLane(targetLane);
        setIsJumping(true); // Se mantiene en true para deshabilitar todos los botones
        setCrashedLane(laneIndex);
        setLaneStates((prev) => {
          const next = [...prev];
          next[laneIndex] = "crashed";
          return next;
        });
        setMessage("¡Cuidado, viene un auto rápido!");
        setCrashPhase('rushing');

        // Tras el recorrido rápido (RUSH_MS), impacta y atropella a la gallina
        crashTimeout.current = setTimeout(() => {
          const hitLeft = START_WIDTH + laneIndex * LANE_WIDTH + LANE_WIDTH / 2;
          setCrashPhase('hit');
          setDeathPosition({ left: hitLeft, top: `${DRAIN_Y_PERCENT}%` });
          setDeathAnimPlaying(true);
          setFallingIn(false);
          setIsJumping(false);
          setMessage(`¡Un auto atropelló a la gallina! Perdiste ${COP.format(bet)}.`);
          notify(`¡Atropellado! Perdiste ${COP.format(bet)}.`);
        }, RUSH_MS);
      }
    }, JUMP_MS);
  }, [gameState, isJumping, crashPhase, currentLane, bet, change, notify]);

  const cashOut = useCallback(() => {
    if (
      gameState !== "playing" ||
      currentLane === 0 ||
      isJumping ||
      isActionLockedRef.current ||
      crashPhase !== "none"
    ) {
      return;
    }
    isActionLockedRef.current = true;
    const winnings = Math.round(bet * currentMultiplier * 100) / 100;
    change(+winnings);
    setGameState("won");
    setFlashWin(winnings);
    notify(`Retiraste a tiempo. Ganaste ${COP.format(winnings)}.`);
    setMessage(`Retiraste a tiempo. Ganaste ${COP.format(winnings)}.`);
  }, [gameState, currentLane, isJumping, crashPhase, bet, currentMultiplier, change, notify]);

  // La posición left es el CENTRO del carril; CSS translate(-50%) lo centra
  const chickenLeft = useMemo(() => {
    if (currentLane === 0) return START_WIDTH / 2;
    return START_WIDTH + (currentLane - 1) * LANE_WIDTH + LANE_WIDTH / 2;
  }, [currentLane]);

  const boardWidth = START_WIDTH + LANE_WIDTH * LANE_COUNT;

  // Cámara que persigue a la gallina:
  // Al inicio (carril 0 o 1) offset = 0, mostrando exactamente el pasto inicial y las 3 primeras alcantarillas.
  // A medida que salta hacia adelante, la cámara se desplaza suavemente persiguiendo a la gallina.
  const cameraOffset = useMemo(() => {
    if (currentLane <= 1) return 0;
    const offset = chickenLeft - 160;
    return Math.max(0, Math.min(boardWidth - VIEWPORT_WIDTH, offset));
  }, [currentLane, chickenLeft, boardWidth]);

  const canJump = gameState === "playing" && !isJumping && !isActionLockedRef.current && crashPhase === 'none' && currentLane < LANE_COUNT;
  const canCashOut = gameState === "playing" && currentLane > 0 && !isJumping && !isActionLockedRef.current && crashPhase === 'none';

  return (
    <div style={styles.outerContainer}>
      {/* ── BARRA DEL CASINO (Como en todos los demás juegos) ── */}
      <GameHeader title={title || "Chicken Road"} name={name} balance={balance} back={back} />

      <div style={styles.page}>
        <style>{css}</style>

        {/* ── SUB-BARRA DE LA MESA (Estilo VIP Lobby de los juegos) ── */}
        <div style={styles.topBar}>
          <div style={styles.titleBlock}>
            <span style={styles.topEmoji}>🐔</span>
            <div>
              <div style={styles.topTitleText}>CHICKEN ROAD</div>
              <div style={styles.topSubtitle}>MESA PRIVADA VIP · DEMO</div>
            </div>
          </div>
          <button onClick={back} style={styles.backBtn}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="15 18 9 12 15 6"/>
            </svg>
            <span>Volver al Lobby</span>
          </button>
        </div>

        {/* ── ÁREA PRINCIPAL: Carretera a la izquierda + Panel a la derecha ── */}
        <div style={styles.gameArea}>
          {/* CARRETERA (Viewport recortado a 3 alcantarillas con cámara dinámica) */}
          <div style={{ ...styles.boardViewport, width: VIEWPORT_WIDTH, height: BOARD_HEIGHT }}>
            <div
              style={{
                ...styles.board,
                width: boardWidth,
                height: BOARD_HEIGHT,
                transform: `translateX(-${cameraOffset}px)`,
                transition: `transform ${JUMP_MS}ms cubic-bezier(0.4, 0, 0.2, 1)`,
              }}
            >
              <div style={{ ...styles.startCol, width: START_WIDTH, backgroundImage: `url(${IMG_ROAD_START})` }}>
                {/* Alcantarilla de spawn de la gallina */}
                <img src={IMG_DRAIN} alt="" style={{ ...styles.drain, top: `${DRAIN_Y_PERCENT}%` }} />
              </div>

              {MULTIPLIERS.map((mult, i) => {
                const state = laneStates[i];
                const { duration, delay } = carTimings[i];
                const isRushingHere = crashPhase === 'rushing' && crashedLane === i;
                const isHitHere     = crashPhase === 'hit'     && crashedLane === i;
                const isConeRushingHere = safeRushLane === i;

                return (
                  <div key={i} style={{ ...styles.lane, width: LANE_WIDTH, left: START_WIDTH + i * LANE_WIDTH, backgroundImage: `url(${IMG_ROAD_REPEAT})` }}>

                    {/* — CARRO según fase — */}
                    {state === 'safe' ? (
                      // Si acaba de salir el cono, el carro baja a toda velocidad y choca contra el cono
                      isConeRushingHere ? (
                        <div className="car car--rush-cone">
                          <TopDownCar tone={CAR_TONES[i % CAR_TONES.length]} />
                        </div>
                      ) : (
                        // Carro detenido encima del cono
                        <div className="car car--stopped" style={{ top: `calc(${DRAIN_Y_PERCENT}% - 88px)` }}>
                          <TopDownCar tone={CAR_TONES[i % CAR_TONES.length]} />
                        </div>
                      )
                    ) : isRushingHere ? (
                      // Carro bajando rápido hacia el pollo
                      <div className="car car--rush">
                        <TopDownCar tone={CAR_TONES[i % CAR_TONES.length]} />
                      </div>
                    ) : isHitHere || state === 'crashed' ? (
                      // Carro estacionado en el punto de impacto
                      <div className="car car--hit" style={{ top: `calc(${DRAIN_Y_PERCENT}% - 28px)` }}>
                        <TopDownCar tone={CAR_TONES[i % CAR_TONES.length]} />
                      </div>
                    ) : (
                      // Carriles normales: animación infinita de autos
                      <div className="car" style={{ ["--dur" as any]: `${duration}s`, ["--delay" as any]: `${delay}s` } as React.CSSProperties}>
                        <TopDownCar tone={CAR_TONES[i % CAR_TONES.length]} />
                      </div>
                    )}

                    <img src={IMG_DRAIN} alt="" style={{ ...styles.drain, top: `${DRAIN_Y_PERCENT}%` }} />

                    {state === 'safe' && (
                      <img src={IMG_CONE} alt="a salvo" className="cone-pop"
                        style={{ ...styles.cone, top: `${DRAIN_Y_PERCENT}%` }} />
                    )}

                    <span style={{
                      ...styles.laneMultLabel,
                      color: state === 'safe' ? '#4fffb0' : state === 'crashed' ? '#ff5c5c' : 'rgba(255,255,255,0.75)',
                    }}>x{mult.toFixed(2)}</span>
                  </div>
                );
              })}

              {/* Gallina: al momento del atropello (crashPhase === 'hit') desaparece INSTANTÁNEAMENTE */}
              {crashPhase !== 'hit' && (
                <img
                  src={IMG_CHICKEN}
                  alt="gallina"
                  className={"chicken" + (jumpArc ? " chicken--jump" : "")}
                  style={{ left: chickenLeft, top: `${DRAIN_Y_PERCENT}%` }}
                />
              )}

              {/* Animación de muerte en pantalla verde (plumas explotando con chroma-key) */}
              <div
                style={{
                  position: "absolute",
                  left: deathPosition ? deathPosition.left : -9999,
                  top: deathPosition ? deathPosition.top : -9999,
                  transform: "translate(-50%, -60%)",
                  zIndex: 10,
                  pointerEvents: "none",
                  opacity: deathAnimPlaying ? 1 : 0,
                  visibility: deathAnimPlaying ? "visible" : "hidden",
                }}
              >
                <ChromaKeyDeath
                  src={deathFeathersVideo}
                  playing={deathAnimPlaying}
                  onEnded={() => setDeathAnimPlaying(false)}
                />
              </div>
            </div>
          </div>

          {/* PANEL DERECHO CON BOTONES Y CONTROLES */}
          <div style={styles.sidePanel}>
            {/* HUD Cards */}
            <div style={styles.hudGrid}>
              <div style={styles.hudCard}>
                <span style={styles.hudLabel}>Multiplicador</span>
                <span style={{ ...styles.hudValue, color: "#ffd23d" }}>x{currentMultiplier.toFixed(2)}</span>
              </div>
              <div style={styles.hudCard}>
                <span style={styles.hudLabel}>Si cobras ahora</span>
                <span style={{ ...styles.hudValue, color: "#3dff8a" }}>
                  {gameState === "playing" && currentLane > 0 ? COP.format(Math.round(potentialWin)) : "—"}
                </span>
              </div>
              <div style={styles.hudCard}>
                <span style={styles.hudLabel}>Carril</span>
                <span style={{ ...styles.hudValue, color: "#a78bfa" }}>{currentLane} / {LANE_COUNT}</span>
              </div>
            </div>

            {/* MENSAJE DE ESTADO */}
            <div style={styles.messageBox}>
              <p style={styles.messageText}>{message}</p>
            </div>

            {/* CONTROLES / BOTONES */}
            <div style={styles.controlsContainer}>
              {gameState === "betting" || gameState === "crashed" || gameState === "won" ? (
                <div style={styles.betPanel}>
                  {/* Selector y ajustes de apuesta */}
                  <div style={styles.betRow}>
                    <button
                      style={styles.quickBtn}
                      onClick={() => setBet((b) => Math.max(10000, Math.floor(b / 2000) * 1000))}
                      title="Mitad de apuesta"
                    >
                      ½
                    </button>
                    <button
                      style={styles.stepBtn}
                      onClick={() => setBet((b) => Math.max(10000, b - 5000))}
                    >
                      −
                    </button>
                    <div style={styles.betDisplay}>
                      <span style={styles.betLabel}>Apuesta</span>
                      <span style={styles.betAmount}>{COP.format(bet)}</span>
                    </div>
                    <button
                      style={styles.stepBtn}
                      onClick={() => setBet((b) => Math.min(balance, b + 5000))}
                    >
                      +
                    </button>
                    <button
                      style={styles.quickBtn}
                      onClick={() => setBet((b) => Math.min(balance, b * 2))}
                      title="Doble de apuesta"
                    >
                      2X
                    </button>
                  </div>

                  {/* Fichas de casino oficiales (10K, 25K, 100K, 500K) */}
                  <div style={styles.chipRow}>
                    {defaultChips.map((c) => (
                      <button
                        key={c}
                        style={{ ...styles.chipBtn, ...(bet === c ? styles.chipBtnActive : {}) }}
                        onClick={() => setBet(Math.min(balance, c))}
                      >
                        {c >= 1000000 ? `${c / 1000000}M` : `${c / 1000}K`}
                      </button>
                    ))}
                    <button
                      style={{ ...styles.chipBtn, background: "rgba(239, 68, 68, 0.15)", color: "#fca5a5" }}
                      onClick={() => setBet(balance)}
                    >
                      MÁX
                    </button>
                  </div>

                  <button
                    style={{
                      ...styles.mainBtn,
                      opacity: bet > balance || bet <= 0 ? 0.5 : 1,
                      cursor: bet > balance || bet <= 0 ? "not-allowed" : "pointer"
                    }}
                    disabled={bet > balance || bet <= 0}
                    onClick={startRound}
                  >
                    🚀 Apostar {COP.format(bet)}
                  </button>
                </div>
              ) : (
                <div style={styles.playCol}>
                  <button
                    style={{ ...styles.jumpBtn, opacity: canJump ? 1 : 0.5, cursor: canJump ? "pointer" : "not-allowed" }}
                    disabled={!canJump}
                    onClick={jump}
                  >
                    🐔 Saltar a la siguiente alcantarilla
                  </button>
                  <button
                    style={{ ...styles.cashBtn, opacity: canCashOut ? 1 : 0.5, cursor: canCashOut ? "pointer" : "not-allowed" }}
                    disabled={!canCashOut}
                    onClick={cashOut}
                  >
                    💰 Cobrar {currentLane > 0 ? COP.format(Math.round(potentialWin)) : ""}
                  </button>
                </div>
              )}
            </div>

            {/* BANNER DE PREMIO */}
            {flashWin !== null && (
              <div style={styles.winBanner}>+{COP.format(Math.round(flashWin))} 🎉 ¡Ganaste!</div>
            )}

            <div style={styles.tipBox}>
              <span>💡 Cada salto exitoso coloca un cono protector que frena los autos en esa vía. ¡Retira cuando quieras!</span>
            </div>
          </div>
        </div>

        <footer style={styles.footer}>Juego de demostración · Fichas virtuales Casino Oasis · Sin dinero real</footer>
      </div>
    </div>
  );
}

