const css = `
@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Outfit:wght@400;600;700&display=swap');

/* La gallina usa translate(-50%, -78%) para centrar+elevar sobre la alcantarilla. */
.chicken {
  position: absolute;
  width: 64px;
  height: 64px;
  image-rendering: pixelated;
  z-index: 5;
  transition: left ${JUMP_MS}ms cubic-bezier(0.45, 0, 0.55, 1);
  transform: translate(-50%, -78%);
}

.chicken--jump {
  animation: jumpArc ${JUMP_MS}ms cubic-bezier(0.45, 0, 0.55, 1) forwards;
}

@keyframes jumpArc {
  0%   { transform: translate(-50%, -78%) translateY(0px); }
  45%  { transform: translate(-50%, -78%) translateY(-52px); }
  100% { transform: translate(-50%, -78%) translateY(0px); }
}

.chicken--fall {
  animation: fallIn 700ms ease-in forwards;
  animation-delay: 60ms;
}

@keyframes fallIn {
  0%   { transform: translate(-50%, -78%) scale(1) rotate(0deg); opacity: 1; }
  55%  { transform: translate(-50%, -30%) scale(0.65) rotate(40deg); opacity: 1; }
  100% { transform: translate(-50%, 10%) scale(0.1) rotate(100deg); opacity: 0; }
}

.car {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  top: -70px;
  animation: driveDown var(--dur, 1.8s) linear infinite;
  animation-delay: var(--delay, 0s);
  z-index: 3;
}

@keyframes driveDown {
  0%   { top: -70px; }
  100% { top: 100%; }
}

.car--hit {
  animation: none !important;
  position: absolute;
  left: 50%;
  transform: translateX(-50%) scale(1.12);
  z-index: 4;
}

/* Carro detenido en carril con cono: sin animacion */
.car--stopped {
  animation: none !important;
  transform: translateX(-50%);
  position: absolute;
  left: 50%;
  z-index: 3;
}

/* Carro bajando rapido a atropellar al pollo (misma velocidad y curva) */
.car--rush {
  animation: rushToChicken ${RUSH_MS}ms cubic-bezier(0.25, 0, 0.9, 0.6) forwards !important;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  top: -70px;
  z-index: 4;
}

@keyframes rushToChicken {
  0%   { top: -70px; }
  100% { top: calc(${DRAIN_Y_PERCENT}% - 28px); }
}

/* Carro bajando rapido con la misma velocidad y aparición a chocar/frenar contra el cono */
.car--rush-cone {
  animation: rushToCone ${RUSH_MS}ms cubic-bezier(0.25, 0, 0.9, 0.6) forwards !important;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  top: -70px;
  z-index: 4;
}

@keyframes rushToCone {
  0%   { top: -70px; }
  100% { top: calc(${DRAIN_Y_PERCENT}% - 88px); }
}

/* El cono aparece encima de la alcantarilla con -130% en el estilo inline. */
.cone-pop {
  animation: conePop 350ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes conePop {
  0%   { transform: translate(-50%, -130%) scale(0.1); opacity: 0; }
  70%  { transform: translate(-50%, -130%) scale(1.15); opacity: 1; }
  100% { transform: translate(-50%, -130%) scale(1);   opacity: 1; }
}
`;
